#include <omp.h>
#include <vector>
#include <cstddef>
#include <limits>

int edgeCount(std::vector<int> const& A, size_t N) {
    // Count only the NxN portion, but never read past A.size().
    size_t total_cells = 0;
    if (N != 0 && N <= std::numeric_limits<size_t>::max() / N) {
        total_cells = N * N;
        if (total_cells > A.size()) {
            total_cells = A.size();
        }
    } else {
        // If N*N would overflow size_t, clamp to the available storage.
        total_cells = A.size();
    }

    long long total = 0;

    #pragma omp parallel for reduction(+:total) schedule(static)
    for (size_t idx = 0; idx < total_cells; ++idx) {
        total += (A[idx] != 0) ? 1LL : 0LL;
    }

    return static_cast<int>(total);
}
